contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 unused) public payable {
        require(unused == unused);
        uint256 beforeBalance = address(c).balance;
        uint256 returned = c.currentBetLimit(); if (__ESBMC_reverted()) return;
        uint256 afterBalance = address(c).balance;
        uint256 returnedAgain = c.currentBetLimit(); if (__ESBMC_reverted()) return;
        assert(returned == returnedAgain && afterBalance == beforeBalance);
    }

    receive() external payable {}
}

