import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 unused) internal {
        vm.assume(unused == unused);
        uint256 beforeBalance = address(c).balance;
        uint256 returned;
        try c.currentBetLimit() returns (uint256 __r) { returned = __r; } catch { return; }
        uint256 afterBalance = address(c).balance;
        uint256 returnedAgain;
        try c.currentBetLimit() returns (uint256 __r) { returnedAgain = __r; } catch { return; }
        assertTrue(returned == returnedAgain && afterBalance == beforeBalance);
    }

    function testFuzz_run(uint256 unused) public {
        _run(unused);
    }

    receive() external payable {}
}
